document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.project').forEach(p=>{p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter});}));
const copy=document.querySelector('#copy');if(copy)copy.addEventListener('click',async function(){try{const email=document.querySelector('.contact-directory a[href^="mailto:"]')?.getAttribute('href')?.slice(7)||'chenhao2026apply@163.com';await navigator.clipboard.writeText(email);this.textContent='邮箱已复制 ✓';setTimeout(()=>this.textContent='复制邮箱 ＋',2200)}catch{this.textContent='chenhao2026apply@163.com'}});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.06});document.querySelectorAll('.project,.about,.steps article,.timeline article').forEach(el=>{el.classList.add('reveal-ready');observer.observe(el)})}
